    @Override
    public void setupAnim(T entity, float limbSwing, float limbSwingAmount,
                          float ageInTicks, float netHeadYaw, float headPitch) {
        this.head.yRot = netHeadYaw * ((float) Math.PI / 180F);
        this.head.xRot = headPitch * ((float) Math.PI / 180F) + 0.10F;
        float amount = Math.min(limbSwingAmount, 1.0F);
        float cycle = limbSwing * 0.6662F * 1.60F;
        float stride = (float) Math.cos(cycle) * 1.00F * amount;
        this.legLeft.xRot = stride;
        this.legRight.xRot = -stride;
        boolean flying = entity != null && !entity.onGround();
        float beat = (float) Math.cos(ageInTicks * 0.9F) * 0.9F + 0.4F;
        this.wingLeft.zRot = flying ? (beat) : (0.25F + (float) Math.abs(Math.sin(cycle * 2.0F)) * 0.9F * amount);
        this.wingRight.zRot = flying ? -(beat) : -(0.25F + (float) Math.abs(Math.sin(cycle * 2.0F)) * 0.9F * amount);
        if (flying) { this.legLeft.xRot = 0.8F; }
        if (flying) { this.legRight.xRot = 0.8F; }
        this.root.y = (float) Math.abs(Math.sin(cycle)) * 0.50F * amount;
        this.root.zRot = (float) Math.sin(cycle) * 0.03F * amount;
    }

    @Override
    public void renderToBuffer(PoseStack pose, VertexConsumer buffer, int light,
                               int overlay, int colour) {
        this.root.render(pose, buffer, light, overlay, colour);
    }
